pub struct ValueInstanceBuilder<'a: 'b, 'b> {
    fbb_: &'b mut flatbuffers::FlatBufferBuilder<'a>,
    start_: flatbuffers::WIPOffset<flatbuffers::TableUnfinishedWIPOffset>,
}
impl<'a: 'b, 'b> ValueInstanceBuilder<'a, 'b> {
    #[inline]
    pub fn add_v_type(&mut self, v_type: Value) {
        self.fbb_
            .push_slot::<Value>(ValueInstance::VT_V_TYPE, v_type, Value::NONE);
    }
    #[inline]
    pub fn add_v(&mut self, v: flatbuffers::WIPOffset<flatbuffers::UnionWIPOffset>) {
        self.fbb_
            .push_slot_always::<flatbuffers::WIPOffset<_>>(ValueInstance::VT_V, v);
    }
    #[inline]
    pub fn add_name(&mut self, name: flatbuffers::WIPOffset<&'b str>) {
        self.fbb_
            .push_slot_always::<flatbuffers::WIPOffset<_>>(ValueInstance::VT_NAME, name);
    }
    #[inline]
    pub fn new(_fbb: &'b mut flatbuffers::FlatBufferBuilder<'a>) -> ValueInstanceBuilder<'a, 'b> {
        let start = _fbb.start_table();
        ValueInstanceBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }
    #[inline]
    pub fn finish(self) -> flatbuffers::WIPOffset<ValueInstance<'a>> {
        let o = self.fbb_.end_table(self.start_);
        self.fbb_.required(o, ValueInstance::VT_V, "v");
        flatbuffers::WIPOffset::new(o.value())
    }
}

